<script setup lang="ts">
const {transactions,totalFees}=useTransactions(); const from=ref(''),to=ref(''),company=ref('')
const rows=computed(()=>transactions.value.filter(t=>{const d=t.createdAt.slice(0,10);return (!from.value||d>=from.value)&&(!to.value||d<=to.value)&&(!company.value||t.companyName===company.value)}));
const companies=computed(()=>[...new Set(transactions.value.map(t=>t.companyName))].sort());
const sums=computed(()=>rows.value.reduce((a,t)=>{a.invoice+=Number(t.finance.invoiceValue||0);a.customs+=Number(t.finance.customsValueIqd||0);a.tax+=Number(t.finance.tax||0);a.fees+=Number(t.finance.customsFees||0);a.decl+=Number(t.finance.declarationFee||0);a.other+=Number(t.finance.otherFees||0);a.total+=totalFees(t);return a},{invoice:0,customs:0,tax:0,fees:0,decl:0,other:0,total:0}));
const daily=computed(()=>{const m:any={};rows.value.forEach(t=>{const d=t.createdAt.slice(0,10);if(!m[d])m[d]={count:0,total:0,tax:0,fees:0};m[d].count++;m[d].total+=totalFees(t);m[d].tax+=Number(t.finance.tax||0);m[d].fees+=Number(t.finance.customsFees||0)});return Object.entries(m).sort((a:any,b:any)=>b[0].localeCompare(a[0]))});function fmt(n:number){return new Intl.NumberFormat('ar-IQ').format(n)}
</script>
<template><div class="page-head"><div><h1>التقارير المالية</h1><p>إجماليات يومية وتراكمية حسب الفترة والشركة</p></div></div><div class="card" style="margin-bottom:16px"><div class="filters"><input v-model="from" type="date" class="input"><input v-model="to" type="date" class="input"><select v-model="company" class="input"><option value="">كل الشركات</option><option v-for="c in companies" :key="c">{{c}}</option></select><button class="btn" @click="from='';to='';company=''">مسح الفلاتر</button></div></div><div class="grid stats"><div class="stat"><small>عدد المعاملات</small><strong>{{rows.length}}</strong></div><div class="stat"><small>إجمالي الضريبة</small><strong>{{fmt(sums.tax)}} د.ع</strong></div><div class="stat"><small>إجمالي الرسوم الجمركية</small><strong>{{fmt(sums.fees)}} د.ع</strong></div><div class="stat"><small>الإجمالي الكلي</small><strong>{{fmt(sums.total)}} د.ع</strong></div></div><div class="card" style="margin-bottom:16px"><h3>تفصيل المجاميع</h3><div class="kv"><div><small>القيمة الجمركية</small><b>{{fmt(sums.customs)}} د.ع</b></div><div><small>رسوم إصدار الإقرار</small><b>{{fmt(sums.decl)}} د.ع</b></div><div><small>رسوم أخرى</small><b>{{fmt(sums.other)}} د.ع</b></div></div></div><div class="card"><h3>الإجمالي حسب التاريخ</h3><div class="table-wrap"><table class="table"><thead><tr><th>التاريخ</th><th>عدد المعاملات</th><th>الضريبة</th><th>الرسوم</th><th>الإجمالي</th></tr></thead><tbody><tr v-for="r in daily" :key="String(r[0])"><td>{{r[0]}}</td><td>{{(r[1] as any).count}}</td><td>{{fmt((r[1] as any).tax)}}</td><td>{{fmt((r[1] as any).fees)}}</td><td><b>{{fmt((r[1] as any).total)}}</b></td></tr><tr v-if="!daily.length"><td colspan="5" class="empty">لا توجد بيانات</td></tr></tbody></table></div></div></template>
